/*
* This script compiles modules for evaluating polynomial and rational functions
* used by the modified Bessel function of the second kind of order zero (K0).
*
* If any coefficients change, this script should be rerun.
*/
'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var readFileSync = require( '@stdlib/fs/read-file' ).sync;
var writeFileSync = require( '@stdlib/fs/write-file' ).sync;
var currentYear = require( '@stdlib/time/current-year' );
var licenseHeader = require( '@stdlib/_tools/licenses/header' );
var compile = require( '@stdlib/math/base/tools/evalrational-compile' );
var compilePoly = require( '@stdlib/math/base/tools/evalpoly-compile' );
var compileC = require( '@stdlib/math/base/tools/evalrational-compile-c' );
var compilePolyC = require( '@stdlib/math/base/tools/evalpoly-compile-c' );
var substringBefore = require( '@stdlib/string/substring-before' );
var substringAfter = require( '@stdlib/string/substring-after' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

// Small-x rational (Boost: P/Q):
var P1 = [
	-1.3725090026855463e-01,
	2.5749161178333129e-01,
	1.3954746021468693e-02,
	5.4454769866539268e-04,
	7.1251594221366221e-06
];

var Q1 = [
	1.000000000000000000e+00,
	-5.4583334380177885e-02,
	1.2910528169752513e-03,
	-1.3676539469785866e-05,
	0.0000000000000000e+00
];

// Small-x polynomial (Boost: P2):
var P2 = [
	1.1593151565841245e-01,
	2.7898287891460317e-01,
	2.5248929932161219e-02,
	8.4603509072136378e-04,
	1.4914719243096175e-05,
	1.6271068924220885e-07,
	1.2082661023927561e-09,
	6.6116863917497043e-12
];

// Large-x rational (Boost: P/Q):
var P3 = [
	2.5331413731550024e-01,
	3.6283421339845952e+00,
	1.8684418894066061e+01,
	4.3062439810634128e+01,
	4.4241162096274282e+01,
	1.5620953393562205e+01,
	-1.8101389782294109e+00,
	-1.4142379942699959e+00,
	-9.3691681197549246e-02
];

var Q3 = [
	1.0,
	1.4941946948799083e+01,
	8.2652964553885542e+01,
	2.1627795066218670e+02,
	2.8451451551842222e+02,
	1.8517144919163350e+02,
	5.4865407174397235e+01,
	6.1180758376289570e+00,
	1.5862612693262351e-01
];

// Header to add to output files:
var header = licenseHeader( 'Apache-2.0', 'js', {
	'year': currentYear(),
	'copyright': 'The Stdlib Authors'
});
header += '\n/* This is a generated file. Do not edit directly. */\n';


// FUNCTIONS //

/**
* Inserts a string between two markers in a text.
*
* @private
* @param {string} text - input text
* @param {string} id - marker id
* @param {string} str - string to insert
* @returns {string} modified text
*/
function insert( text, id, str ) {
	var before;
	var after;

	before = substringBefore( text, '// BEGIN: '+id );
	after = substringAfter( text, '// END: '+id );

	return format( '%s// BEGIN: %s\n\n%s\n// END: %s%s', before, id, str, id, after );
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var fpath;
	var copts;
	var opts;
	var file;

	opts = {
		'encoding': 'utf8'
	};

	// JS evaluators:
	fpath = resolve( __dirname, '..', 'lib', 'rational_p1q1.js' );
	writeFileSync( fpath, header + compile( P1, Q1 ), opts );

	fpath = resolve( __dirname, '..', 'lib', 'poly_p2.js' );
	writeFileSync( fpath, header + compilePoly( P2 ), opts );

	fpath = resolve( __dirname, '..', 'lib', 'rational_p3q3.js' );
	writeFileSync( fpath, header + compile( P3, Q3 ), opts );

	// C evaluators:
	copts = {
		'dtype': 'double',
		'name': ''
	};
	fpath = resolve( __dirname, '..', 'src', 'main.c' );
	file = readFileSync( fpath, opts );

	copts.name = 'rational_p1q1';
	file = insert( file, copts.name, compileC( P1, Q1, copts ) );

	copts.name = 'poly_p2';
	file = insert( file, copts.name, compilePolyC( P2, copts ) );

	copts.name = 'rational_p3q3';
	file = insert( file, copts.name, compileC( P3, Q3, copts ) );

	writeFileSync( fpath, file, opts );
}

main();
